-- D-2026-11-09-13 / tickets 408-409: the Admin-managed profile character library. Additive: one new
-- table, seeded with the 24 mock characters under the SAME ids, images, shown flags and upload
-- order, so every stored `character:<id>` picture keeps resolving (id '' included). Owner approved
-- the migration (November 11, 2026); apply to a shared database only after human sign-off.
-- Uploaded images live in the public Supabase Storage bucket `profile-characters` (created by hand
-- in the dashboard, as `player-avatars` was); seeded rows keep their data: URL images.

-- CreateTable
CREATE TABLE "profile_characters" (
    "id" TEXT NOT NULL,
    "image" TEXT NOT NULL,
    "shown" BOOLEAN NOT NULL DEFAULT true,
    "uploaded_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "number" INTEGER NOT NULL,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "profile_characters_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "profile_characters_number_key" ON "profile_characters"("number");

-- CreateIndex
CREATE INDEX "profile_characters_uploaded_at_number_idx" ON "profile_characters"("uploaded_at", "number");


-- Seeded ids are '' or one lowercase letter; uploads use a lowercase UUID chosen by the Admin client.
ALTER TABLE "profile_characters"
  ADD CONSTRAINT "profile_characters_id_format" CHECK (
    "id" ~ '^[a-z]?$' OR "id" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  ADD CONSTRAINT "profile_characters_image_reference" CHECK (
    "image" LIKE 'data:image/%' OR "image" LIKE 'https://%'
  ),
  ADD CONSTRAINT "profile_characters_number_positive" CHECK ("number" > 0);

-- The 24 mock characters (packages/data/src/profile-character/characters.json), all shown, in
-- upload order: "Character 1" … "Character 24", one millisecond apart.
